mapper.select:
SELECT p.prod_id,p.prod_name FROM chb_prd_baseinfo p where p.status in ('E')
AND P.PROD_ID LIKE concat_ws(concat_ws('%', #{search}),'%') or p.prod_name like concat_ws(concat_ws('%', #{search}),'%')
AND P.PROD_ID = #{initValue}

	SELECT count(1) from (
SELECT 1 from PRD_FEE_RATE_DATA a
	where a.STATUS in('A','E')
	and not EXISTS (
	 SELECT 1 from 	DIS_PRD_FEE_RATE_ERRORDATA b
			WHERE b.PROD_ID=a.PROD_ID
				and b.CASH_TYPE_2=a.CASH_TYPE_2
			and b.START_DATE=a.START_DATE
			and b.STATUS in('A','E')
	)

	a.PROD_ID = #{item.prodId,jdbcType=VARCHAR}
	and a.START_DATE = #{item.startDate,jdbcType=DATE}
	and a.CASH_TYPE_2 = #{item.cashType2,jdbcType=VARCHAR}

	union all
	SELECT 1 from DIS_PRD_FEE_RATE_ERRORDATA c
	where c.STATUS in('A','E')

	c.PROD_ID = #{item.prodId,jdbcType=VARCHAR}
	and c.START_DATE = #{item.startDate,jdbcType=DATE}
	and c.CASH_TYPE_2 = #{item.cashType2,jdbcType=VARCHAR}

)tmp
